# (key, en name, en desc, fr name, fr desc, de name, de desc, es name, es desc)
# Vessels and heart, part 3.

NO = ("", "", "", "")
ACC = ("Accompanies the artery of the same name.", "Accompagne l'artère homonyme.",
       "Begleitet die gleichnamige Arterie.", "Acompaña a la arteria homónima.")
SEGA = ("Branch of the pulmonary artery to a segment of the {s} lung; it runs with the segmental bronchus and carries deoxygenated blood to the alveoli.",
        "Branche de l'artère pulmonaire destinée à un segment du poumon {s} ; elle accompagne la bronche segmentaire et conduit le sang désoxygéné aux alvéoles.",
        "Ast der Lungenarterie zu einem Segment der {s} Lunge; begleitet den Segmentbronchus und bringt sauerstoffarmes Blut zu den Alveolen.",
        "Rama de la arteria pulmonar para un segmento del pulmón {s}; acompaña al bronquio segmentario y lleva sangre desoxigenada a los alvéolos.")
LV = ("Runs in the plane between segments and carries oxygenated blood to the pulmonary veins; it marks the segment boundaries in segmentectomy.",
      "Chemine dans le plan intersegmentaire et conduit le sang oxygéné vers les veines pulmonaires ; repère des limites segmentaires lors d'une segmentectomie.",
      "Verläuft in der Ebene zwischen den Segmenten und führt sauerstoffreiches Blut zu den Lungenvenen; markiert bei der Segmentresektion die Segmentgrenzen.",
      "Discurre en el plano intersegmentario y lleva sangre oxigenada a las venas pulmonares; marca los límites segmentarios en la segmentectomía.")
GEN = ("Branch of the anastomosis around the knee joint.", "Branche de l'anastomose péri-articulaire du genou.",
       "Ast des Gefäßnetzes um das Kniegelenk.", "Rama de la anastomosis alrededor de la rodilla.")
SIDE = {"left": ("left", "gauche", "linken", "izquierdo", "sinistra", "linke"),
        "right": ("right", "droit", "rechten", "derecho", "dextra", "rechte")}


def T(key, en, fr, de, es, d=NO):
    return (key, en, d[0], fr, d[1], de, d[2], es, d[3])


def seg(key, side, en, fr, de, es):
    s = SIDE[side]
    d = tuple(x.format(s=s[i]) for i, x in enumerate(SEGA))
    return T(key, f"{en} segmental artery of {s[0]} lung", f"Artère segmentaire {fr} du poumon {s[1]}",
             f"A. segmentalis {de} ({s[5]} Lunge)", f"Arteria segmentaria {es} del pulmón {s[3]}", d)


def lvein(key, side, en, fr, de, es):
    s = SIDE[side]
    return T(key, f"{en} vein of {s[0]} lung", f"Veine {fr} du poumon {s[1]}",
             f"V. {de} ({s[5]} Lunge)", f"Vena {es} del pulmón {s[3]}", LV)


def lobar(key, side, en, fr, de, es):
    s = SIDE[side]
    d = (f"Branch of the pulmonary artery to the {en.lower()} lobe of the {s[0]} lung.",
         f"Branche de l'artère pulmonaire destinée au lobe {fr} du poumon {s[1]}.",
         f"Ast der Lungenarterie zum {de}lappen der {s[2]} Lunge.",
         f"Rama de la arteria pulmonar para el lóbulo {es} del pulmón {s[3]}.")
    la = {"Superior": "superior", "Inferior": "inferior", "Middle": "media"}[en]
    return T(key, f"{en} lobar artery of {s[0]} lung", f"Artère lobaire {fr} du poumon {s[1]}",
             f"A. lobaris {la} ({s[5]} Lunge)", f"Arteria lobular {es} del pulmón {s[3]}", d)


